                FieldName = "Code",
                FieldsDataType = "Text",
                IsRequired = true,
                MaxLength = 4,
                MinLength = 0,
                ObjectTableId = INTTRADocumentTypeObject.Id,
                ObjectTableName = INTTRADocumentTypeObject.Name,
                Tenant = 0,
                TextCodeType = "F",
                ListFieldLable = "CodeListLable",
                ListLableDefaultText = "Code",
                DisplayInList = true,
                CanFilter = true,
                Operator = "StartsWith",
                ListPropertyPath = "Code",
