        #region check for new queries

        public IQueryable<QueryPM> CheckForNewQueries(int tenant, string userId)
        {

            List<Query> QueriesList = QueriesRepository.GetQueriesByTenant(tenant).ToList();
            List<QueryColumn> QueryColumnsList = QueryColumnsRepository.GetQueryColumnsByTenant(tenant).ToList();
            List<AdvancedQueryFilter> AdvancedFiltersList = AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenant(tenant).ToList();


            List<Query> SystemQueries = QueriesList.Where(d => d.SystemLevel == true && d.UserId == null).ToList(); //QueriesRepository.GetQueriesByTenantSystemLevel(tenant).ToList();
            List<Query> TenantQueries = QueriesList.Where(d => d.TenantLevel == true && d.UserId == null).ToList(); //QueriesRepository.GetQueriesByTenantTenantLevel(tenant).ToList();
            List<Query> UsersQueries = QueriesList.Where(d => d.UserId == userId).ToList();//QueriesRepository.GetQueryByTenantAndUser(tenant, userId).ToList();

            UserRepository userRep = new UserRepository();
            bool DoSubmittChanges = false;
            User user = userRep.GetSingleUser(userId, tenant, false);
            if (user != null)
            {
                //----if no queries for user.
                if (UsersQueries.Count() == 0)
                {
                    DoSubmittChanges = true;
                    foreach (Query query in SystemQueries)
                    {
                        List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == query.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, query.Id).ToList();
                        List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == query.Id && d.Tenant == tenant).ToList();//AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, query.Id).ToList();

                        Query newQuery = new Query()
                        {
                            Tenant = tenant,
                            UserId = userId,
                            OriginalQueryId = query.Id,
                            Id = IdCounter.GetNumber("Query", tenant).ToString(),
                            ObjectTableId = query.ObjectTableId,
                            QuerySection = query.QuerySection,
                            Code = query.Code,
                            SystemLevel = query.SystemLevel,
                            TenantLevel = query.TenantLevel,
                            IndexOrder = query.IndexOrder,
                            DisplayCount = query.DisplayCount,
                            QueryGroupCode = query.QueryGroupCode,
                            IsAddNewEntityEnabled = query.IsAddNewEntityEnabled,
                            DefaultSortColumn = query.DefaultSortColumn,
                            DefaultSortDirection = query.DefaultSortDirection,
                            NameTextCodeId = query.NameTextCodeId,
                            SpotlightDataTemplate = query.SpotlightDataTemplate,
                        };
                        QueriesRepository.Add(newQuery);

                        foreach (QueryColumn column in queryColumns)
                        {
                            QueryColumn newColumn = new QueryColumn()
                            {
                                ColumnWidth = column.ColumnWidth,
                                Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                IndexOrder = column.IndexOrder,
                                ObjectFieldId = column.ObjectFieldId,
                                QueryId = newQuery.Id,
                                Tenant = tenant,


                            };
                            QueryColumnsRepository.Add(newColumn);
                        }

                        foreach (AdvancedQueryFilter filter in advancedFilters)
                        {
                            AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                            {
                                QueryId = newQuery.Id,
                                Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                Tenant = tenant,
                                PredefinedValue = filter.PredefinedValue,
                                ObjectFieldId = filter.ObjectFieldId,
                                IsPredefined = filter.IsPredefined,

                            };
                            AdvancedQueryFiltersRepository.Add(newFilter);
                        }




                    }
                }
                //--------------if there is queries for the user.
                else
                {
                    //------check for system queries.
                    bool notExistsInSystem = true;
                    foreach (Query sysQuery in SystemQueries)
                    {
                        notExistsInSystem = true;
                        foreach (Query query in UsersQueries)
                        {
                            if (query.OriginalQueryId == sysQuery.Id)
                            {
                                notExistsInSystem = false;
                                break;
                            }
                        }

                        if (notExistsInSystem)
                        {
                            DoSubmittChanges = true;
                            List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == sysQuery.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, sysQuery.Id).ToList();
                            List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == sysQuery.Id && d.Tenant == tenant).ToList(); //AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, sysQuery.Id).ToList();

                            Query newQuery = new Query()
                            {
                                Tenant = tenant,
                                UserId = userId,
                                OriginalQueryId = sysQuery.Id,
                                Id = IdCounter.GetNumber("Query", tenant).ToString(),
                                ObjectTableId = sysQuery.ObjectTableId,
                                QuerySection = sysQuery.QuerySection,
                                Code = sysQuery.Code,
                                DisplayCount = sysQuery.DisplayCount,
                                QueryGroupCode = sysQuery.QueryGroupCode,
                                IsAddNewEntityEnabled = sysQuery.IsAddNewEntityEnabled,
                                NameTextCodeId = sysQuery.NameTextCodeId,
                                IndexOrder = sysQuery.IndexOrder,
                                SystemLevel = sysQuery.SystemLevel,
                                DefaultSortColumn = sysQuery.DefaultSortColumn,
                                DefaultSortDirection = sysQuery.DefaultSortDirection,
                                TenantLevel = sysQuery.TenantLevel,
                                SpotlightDataTemplate = sysQuery.SpotlightDataTemplate,


                            };

                            QueriesRepository.Add(newQuery);

                            foreach (QueryColumn column in queryColumns)
                            {
                                QueryColumn newColumn = new QueryColumn()
                                {
                                    ColumnWidth = column.ColumnWidth,
                                    Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                    IndexOrder = column.IndexOrder,
                                    ObjectFieldId = column.ObjectFieldId,
                                    QueryId = newQuery.Id,
                                    Tenant = tenant,

                                };
                                QueryColumnsRepository.Add(newColumn);
                            }

                            foreach (AdvancedQueryFilter filter in advancedFilters)
                            {
                                AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                                {
                                    QueryId = newQuery.Id,
                                    Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                    Tenant = tenant,
                                    PredefinedValue = filter.PredefinedValue,
                                    ObjectFieldId = filter.ObjectFieldId,
                                    IsPredefined = filter.IsPredefined,

                                };
                                AdvancedQueryFiltersRepository.Add(newFilter);
                            }


                        }

                    }
                    //------ check for tenant queries.


                    bool notExistInTenant = true;
                    foreach (Query tenantQuery in TenantQueries)
                    {
                        notExistInTenant = true;
                        foreach (Query query in UsersQueries)
                        {
                            if (query.OriginalQueryId == tenantQuery.Id)
                            {
                                notExistInTenant = false;
                                break;
                            }
                        }

                        if (notExistInTenant)
                        {
                            DoSubmittChanges = true;
                            List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == tenantQuery.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, tenantQuery.Id).ToList();
                            List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == tenantQuery.Id && d.Tenant == tenant).ToList();//AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, tenantQuery.Id).ToList();

                            Query newQuery = new Query()
                            {
                                Tenant = tenant,
                                UserId = userId,
                                OriginalQueryId = tenantQuery.Id,
                                Id = IdCounter.GetNumber("Query", tenant).ToString(),
                                ObjectTableId = tenantQuery.ObjectTableId,
                                QuerySection = tenantQuery.QuerySection,
                                Code = tenantQuery.Code,
                                SystemLevel = tenantQuery.SystemLevel,
                                TenantLevel = tenantQuery.TenantLevel,
                                IndexOrder = tenantQuery.IndexOrder,
                                DisplayCount = tenantQuery.DisplayCount,
                                QueryGroupCode = tenantQuery.QueryGroupCode,
                                IsAddNewEntityEnabled = tenantQuery.IsAddNewEntityEnabled,
                                NameTextCodeId = tenantQuery.NameTextCodeId,
                                DefaultSortDirection = tenantQuery.DefaultSortDirection,
                                DefaultSortColumn = tenantQuery.DefaultSortColumn,
                                SpotlightDataTemplate = tenantQuery.SpotlightDataTemplate,
                            };
                            QueriesRepository.Add(newQuery);

                            foreach (QueryColumn column in queryColumns)
                            {
                                QueryColumn newColumn = new QueryColumn()
                                {
                                    ColumnWidth = column.ColumnWidth,
                                    Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                    IndexOrder = column.IndexOrder,
                                    ObjectFieldId = column.ObjectFieldId,
                                    QueryId = newQuery.Id,
                                    Tenant = tenant,



                                };
                                QueryColumnsRepository.Add(newColumn);
                            }

                            foreach (AdvancedQueryFilter filter in advancedFilters)
                            {
                                AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                                {
                                    QueryId = newQuery.Id,
                                    Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                    Tenant = tenant,
                                    PredefinedValue = filter.PredefinedValue,
                                    ObjectFieldId = filter.ObjectFieldId,
                                    IsPredefined = filter.IsPredefined,


                                };
                                AdvancedQueryFiltersRepository.Add(newFilter);
                            }




                        }

                    }

                }
                if (DoSubmittChanges)
                {
                    QueriesRepository.SubmitChanges();
                    QueryColumnsRepository.SubmitChanges();
                    AdvancedQueryFiltersRepository.SubmitChanges();
                }


            }

            QueryQuery queryQuery = new QueryQuery(QueriesRepository);
            IQueryable<QueryPM> FinalUsersQuery = queryQuery.GetQueryByTenantAndUser(tenant, userId);
            return FinalUsersQuery;
        }
        #endregion

        public List<ObjectFieldPM> LoadObjectFieldsToTenant(int tenant)
        {
            objectFieldsQuery = new ObjectFieldQuery(ObjectFieldsRepository);
            List<ObjectFieldPM> TenantZeroObjectFields = objectFieldsQuery.GetObjectFieldPMsByTenant(0, tenant).ToList();
            List<ObjectTable> TenantZeroObjectTables = ObjectTableRepository.GetObjectsByTenant(0).ToList();
            List<ObjectTable> CurrentTenantObjectTables = ObjectTableRepository.GetObjectsByTenant(tenant).ToList();
            List<TextCode> TenantZeroTextCodes = TextCodeRepository.GetTextCodesByTenant(0).ToList();
            Dictionary<string, TextCode> CurrentTenantTextCodes = TextCodeRepository.GetTextCodesByTenant(tenant).ToDictionary(d => d.Code + d.Tenant + d.ObjectTableId, a => a);

            foreach (ObjectFieldPM zeroObject in TenantZeroObjectFields)
            {
                ObjectTable zeroObjectTable = TenantZeroObjectTables.Where(d => d.Id == zeroObject.ObjectTableId).FirstOrDefault();
                ObjectTable currentObjectTable = CurrentTenantObjectTables.Where(d => d.Name == zeroObjectTable.Name).FirstOrDefault();


                ObjectTable zeroLookUpTable = null;
                ObjectTable currentLookUpTable = null;
                if (zeroObject.LookUpTableId != null)
                {
                    zeroLookUpTable = TenantZeroObjectTables.Where(d => d.Id == zeroObject.LookUpTableId).FirstOrDefault();
                    currentLookUpTable = CurrentTenantObjectTables.Where(d => d.Name == zeroLookUpTable.Name).FirstOrDefault();
                }
                ObjectTable zeroMultiTable = null;
                ObjectTable currentMultiTable = null;
                if (zeroObject.MultiTableId != null)
                {
                    zeroMultiTable = TenantZeroObjectTables.Where(d => d.Id == zeroObject.MultiTableId).FirstOrDefault();
                    currentMultiTable = CurrentTenantObjectTables.Where(d => d.Name == zeroMultiTable.Name).FirstOrDefault();
                }


                TextCode zeroShortTextCode = null;
                TextCode currentShortTextCode = null;
                if (zeroObject.ShortNameTextCodeId != null)
                {
                    zeroShortTextCode = TenantZeroTextCodes.Where(d => d.Id == zeroObject.ShortNameTextCodeId).FirstOrDefault();
                    currentShortTextCode = CurrentTenantTextCodes[zeroShortTextCode.Code + tenant + currentObjectTable.Id];
                }

                TextCode zerofullTextCode = TenantZeroTextCodes.Where(d => d.Id == zeroObject.FullNameTextCodeId).FirstOrDefault();
                TextCode CurrentfullTextCode = CurrentTenantTextCodes[zerofullTextCode.Code + tenant + currentObjectTable.Id];

                TextCode zeroListTextCode = null;
                TextCode currentListTextCode = null;
                if (zeroObject.ListTextCodeId != null)
                {
                    zeroListTextCode = TenantZeroTextCodes.Where(d => d.Id == zeroObject.ListTextCodeId).FirstOrDefault();
                    currentListTextCode = CurrentTenantTextCodes[zeroListTextCode.Code + tenant + currentObjectTable.Id];
                }

                TextCode zeroHelpTextCode = TenantZeroTextCodes.Where(d => d.Id == zeroObject.HelpTextCodeId).FirstOrDefault();
                TextCode CurrentHelpTextCode = CurrentTenantTextCodes[zeroHelpTextCode.Code + tenant + currentObjectTable.Id];


                ObjectField newObjectField = new ObjectField()
                {
                    AutomaticField = zeroObject.AutomaticField,
                    CanFilter = zeroObject.CanFilter,
                    ConverterName = zeroObject.ConverterName,
                    DataTemplateName = zeroObject.DataTemplateName,
                    DataTypeCode = zeroObject.DataTypeCode,
                    DependencyFilter1Type = zeroObject.DependencyFilter1Type,
                    DependencyFilter1Value = zeroObject.DependencyFilter1Value,
                    DependencyFilter2Type = zeroObject.DependencyFilter2Type,
                    DependencyFilter2Value = zeroObject.DependencyFilter2Value,
                    DigitsAfterPoint = zeroObject.DigitsAfterPoint,
                    DisplayInEntityVariables = zeroObject.DisplayInEntityVariables,
                    DisplayInList = zeroObject.DisplayInList,
                    DisplayInLookUpIndex = zeroObject.DisplayInLookUpIndex,
                    DisplayInSearchWindowFilters = zeroObject.DisplayInSearchWindowFilters,
                    DisplayInSearchWindowFiltersIndex = zeroObject.DisplayInSearchWindowFiltersIndex,
                    DisplayInSearchWindowList = zeroObject.DisplayInSearchWindowList,
                    DisplayInSearchWindowListIndex = zeroObject.DisplayInSearchWindowListIndex,
                    DisplayOnLookUp = zeroObject.DisplayOnLookUp,
                    DisplayOnly = zeroObject.DisplayOnly,
                    FieldName = zeroObject.FieldName,
                    FullNameTextCodeId = CurrentfullTextCode.Id,
                    HelpTextCodeId = CurrentHelpTextCode != null ? CurrentHelpTextCode.Id : null,
                    ListTextCodeId = currentListTextCode != null ? currentListTextCode.Id : null,
                    ObjectTableId = currentObjectTable.Id,
                    ShortNameTextCodeId = currentShortTextCode != null ? currentShortTextCode.Id : null,
                    Id = IdCounter.GetNumber("ObjectField", tenant).ToString(),
                    IsCustom = zeroObject.IsCustom,
                    IsCustomFilter = zeroObject.IsCustomFilter,
                    IsMulti = zeroObject.IsMulti,
                    IsRequiered = zeroObject.IsRequiered,
                    IsRestrictable = zeroObject.IsRestrictable,
                    IsTimeFrameFilter = zeroObject.IsTimeFrameFilter,
                    ListPropertyPath = zeroObject.ListPropertyPath,
                    LookUpControlName = zeroObject.LookUpControlName,
                    LookUpTableId = currentLookUpTable != null ? currentLookUpTable.Id : null,
                    MaxLength = zeroObject.MaxLength,
                    MinLength = zeroObject.MinLength,
                    MultiLine = zeroObject.MultiLine,
                    MultiTableId = currentMultiTable != null ? currentMultiTable.Id : null,
                    Operator = zeroObject.Operator,
                    PMPropertyPath = zeroObject.PMPropertyPath,
                    SystemMaxLength = zeroObject.SystemMaxLength,
                    SystemRequired = zeroObject.SystemRequired,
                    Tenant = tenant,
                    TextCase = zeroObject.TextCase,
                    UniqueField = zeroObject.UniqueField,
                    ValidForQuerySection1 = zeroObject.ValidForQuerySection1,
                    ValidForQuerySection2 = zeroObject.ValidForQuerySection2,

                };
                ObjectFieldsRepository.Add(newObjectField);

                foreach (ObjectFieldValidationPM validation in zeroObject.ObjectFieldValidations)
                {
                    ObjectFieldValidation newValidation = new ObjectFieldValidation()
                    {
                        Condition = validation.Condition,
                        ErrorMessage = validation.ErrorMessage,
                        Id = IdCounter.GetNumber("ObjectFieldValidation", tenant).ToString(),
                        ObjectFieldId = newObjectField.Id,
                        Tenant = tenant,
                        ValidationOrder = validation.ValidationOrder,
                        ValidationExpression = validation.ValidationExpression,
                        ObjectFieldCode = newObjectField.FieldCode,
                        Code = validation.Code,
                    };
                    ObjectFieldValidationRepository.Add(newValidation);
                }

            }
            ObjectFieldsRepository.SubmitChanges();
            ObjectFieldValidationRepository.SubmitChanges();

            objectFieldsQuery = new ObjectFieldQuery(ObjectFieldsRepository);
            List<ObjectFieldPM> objectfieldPMs = objectFieldsQuery.GetObjectFieldPMsByTenant(tenant, tenant);
            return objectfieldPMs;

        }

        #region Features
        public void LoadRolesAndFeatures(int tenant)
        {
            ICommonDataContext ObjectContext = CommonDataContext.GetContext(tenant);
            FeatureRepository FeaturesRepository = new FeatureRepository(ObjectContext);
            RoleFeatureRepository RoleFeaturesRepository = new RoleFeatureRepository(ObjectContext);
            TextCodeRepository textCodeRep = new TextCodeRepository(tenant);
            ObjectTableRepository objecttableRep = new ObjectTableRepository(tenant);
            objectTabelQuery = new ObjectTableQuery(objecttableRep);

            List<ObjectTablePM> objectTables = objectTabelQuery.GetObjectPMsByTenant(tenant).ToList();

            #region object tables
            ObjectTablePM ShipmentObjectTable = objectTables.Where(d => d.Name == "Shipment").FirstOrDefault();
            ObjectTablePM MasterObjectTable = objectTables.Where(d => d.Name == "Master").FirstOrDefault();
            ObjectTablePM GeneralObjectTable = objectTables.Where(d => d.Name == "General").FirstOrDefault();
            ObjectTablePM CustomerObjectTable = objectTables.Where(d => d.Name == "Customer").FirstOrDefault();
            ObjectTablePM AgentObjectTable = objectTables.Where(d => d.Name == "Agent").FirstOrDefault();
            ObjectTablePM CustomAgentObjectTable = objectTables.Where(d => d.Name == "CustomAgent").FirstOrDefault();
            ObjectTablePM ShippingAgentObjectTable = objectTables.Where(d => d.Name == "ShippingAgent").FirstOrDefault();
            ObjectTablePM AirlineObjectTable = objectTables.Where(d => d.Name == "Airline").FirstOrDefault();
            ObjectTablePM ShippingLineObjectTable = objectTables.Where(d => d.Name == "ShippingLine").FirstOrDefault();
            ObjectTablePM TruckerObjectTable = objectTables.Where(d => d.Name == "Trucker").FirstOrDefault();
            ObjectTablePM IncotermObjectTable = objectTables.Where(d => d.Name == "Incoterm").FirstOrDefault();
